test("person timeline scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  await expect(pg_vic.getByTestId("rollup-due-total")).toHaveText("3.29");
  await expect(pg_vic.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("rollup-settled-total")).toHaveText("2.00");
  await expect(pg_vic.getByTestId("rollup-open-total")).toHaveText("1.29");
  await expect(pg_vic.getByTestId("bulk-settle-batch")).toHaveText("1");
  await expect(pg_vic.getByTestId("rollup-cut-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("rollup-aged-0-30")).toHaveText("1.29");
  await expect(pg_vic.getByTestId("rollup-aged-31-60")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("rollup-aged-61")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("header-people-count")).toHaveText("1");
  await expect(pg_vic.getByTestId("header-claims-DRAFT-count")).toHaveText("1");
  await expect(pg_vic.getByTestId("header-claims-OPEN-count")).toHaveText("1");
  await expect(pg_vic.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("header-claims-SETTLED-count")).toHaveText("2");
  await expect(pg_vic.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("header-claims-REVIEW-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("header-due-total")).toHaveText("3.29");
  await expect(pg_vic.getByTestId("header-overdue-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("my-due-total")).toHaveText("");
  await expect(pg_vic.getByTestId("my-overdue-total")).toHaveText("");
  await expect(pg_vic.getByTestId("my-crew-due-total")).toHaveText("");
  await expect(pg_vic.getByTestId("my-reviews-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("watched-due-total")).toHaveText("0.00");
  expect(await ui.setSettingDated(pg_vic, "floor", "3.00", "2026-03-15", "1.00")).toBe(true);
  expect(await ui.setRate(pg_vic, {"grade": "C", "pct": "12.50"})).toBe(true);
  expect(await ui.addLine(pg_vic, c_ben_3, {"label": "x", "qty": "3", "unit": "2.50"})).toBe(true);
  expect(await ui.exportCsv(pg_vic)).toBe("name,grade,retired-from,due-total\nBen,A,,5.00\n");
  expect(await ui.claimEditOpen(pg_vic, c_ben_3)).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.claimEditOpen(pg_uma, c_ben_3)).toBe(false);
  await ui.refresh(pg_vic);
  expect(await ui.claimEditSave(pg_vic, c_ben_3, {"amount": "20.00"})).toBe(false);
  const c_ben_4 = ui.must(await ui.addClaim(pg_vic, p_ben, {"amount": "7.77", "date": "2026-03-05", "tags": "a, B"}));
  expect(await ui.setRate(pg_vic, {"grade": "A", "pct": "20.00"})).toBe(true);
  await ui.refresh(pg_vic);
  await expect(pg_vic.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("17.68");
  await expect(pg_vic.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("5.00");
